action.command:
node -e "
const d = JSON.parse(require('fs').readFileSync('/workspace/.devcontainer/keycloak/imports/startuphafen.json','utf8'));
const c = d.clients.find(x=>x.clientId==='startuphafen_app');
console.log('redirectUris:', JSON.stringify(c.redirectUris));
console.log('webOrigins:', JSON.stringify(c.webOrigins));
console.log('baseUrl:', c.baseUrl);
console.log('publicClient:', c.publicClient);
console.log('standardFlow:', c.standardFlowEnabled, 'direct:', c.directAccessGrantsEnabled);
console.log('roles:', c.roles && c.roles.stream ? 'map' : JSON.stringify(c.roles));
console.log('defaultClientScopes:', (c.defaultClientScopes||[]).join(','));
"

